import type { Capsule } from "./data";

// YKS TYT/AYT için genişletilmiş mikro-öğrenme kapsülleri (200+ konu)
export const extraCapsules: Capsule[] = [
  // ==================== TÜRKÇE ====================
  { id: "tr6", category: "turkce", title: "Eş Anlamlı Sözcükler", summary: "Yazılışları farklı, anlamları aynı olan sözcüklerdir: kara-siyah, cevap-yanıt.", detail: "Eş anlamlılar (anlamdaş) cümlede birbirinin yerine kullanılabilir; biri Türkçe biri yabancı kökenli olabilir. Ancak her bağlamda birbirinin yerine geçemezler.", funFact: "'Kara bahtım' yerine 'siyah bahtım' denmez; deyimlerde eş anlamlı değişimi bozukluk yaratır.", tags: ["sözcükte anlam", "eş anlam"], difficulty: "Temel" },
  { id: "tr7", category: "turkce", title: "Zıt (Karşıt) Anlam", summary: "Anlamca birbirinin karşıtı olan sözcüklerdir: uzun-kısa, iyi-kötü.", detail: "Olumsuzluk eki almış bir sözcük her zaman zıt anlamlı sayılmaz. 'Var' ile 'yok' zıt anlamlıdır ama 'sıcak' ile 'soğuk' karşıt kutuplardır.", funFact: "Her sözcüğün zıttı olmayabilir; 'masa' sözcüğünün karşıtı yoktur.", tags: ["sözcükte anlam", "zıt anlam"], difficulty: "Temel" },
  { id: "tr8", category: "turkce", title: "Terim Anlam", summary: "Bir bilim, sanat veya meslek dalına özgü, özel anlam taşıyan sözcüklerdir.", detail: "'Kök, üs, açı' matematik terimleri; 'perde, sahne' tiyatro terimleridir. Aynı sözcük hem genel hem terim anlam taşıyabilir: 'kök' (bitki) ve 'kök' (matematik).", funFact: "Bir sözcüğün terim mi genel mi olduğunu bağlam belirler.", tags: ["sözcükte anlam", "terim"], difficulty: "Orta" },
  { id: "tr9", category: "turkce", title: "Deyimler", summary: "Kalıplaşmış, genellikle mecaz anlam taşıyan en az iki sözcüklü söz öbekleridir.", detail: "Deyimlerin sözcükleri değiştirilemez, sırası bozulamaz. Çoğu mecaz anlamlıdır: 'etekleri zil çalmak' çok sevinmek demektir. Bazıları gerçek anlamlıdır: 'çoğu gitti azı kaldı'.", funFact: "Deyimler yargı bildirmez, atasözleri bildirir; bu ikisini karıştırma.", tags: ["deyim", "söz varlığı"], difficulty: "Orta" },
  { id: "tr10", category: "turkce", title: "Atasözleri", summary: "Uzun deneyimlerden doğan, öğüt veren, kalıplaşmış yargı bildiren sözlerdir.", detail: "Atasözleri genel bir kural veya deneyim aktarır: 'Damlaya damlaya göl olur.' Deyimden farkı yargı bildirmesidir. Söyleyeni belli değildir, anonimdir.", funFact: "Atasözü cümle halindedir ve bir yargı içerir; deyim ise kavramı karşılar.", tags: ["atasözü", "söz varlığı"], difficulty: "Temel" },
  { id: "tr11", category: "turkce", title: "Ses Olayları: Ünsüz Yumuşaması", summary: "p, ç, t, k sert ünsüzleri ünlüyle başlayan ek alınca b, c, d, g/ğ'ye dönüşür.", detail: "'kitap → kitabı', 'ağaç → ağacı', 'renk → rengi'. Tek heceli birçok sözcükte yumuşama olmaz: 'top → topu'. Özel isimlerde yazıda gösterilmez.", funFact: "'Ahmet'in' yazılır ama 'Ahmedin' yazılmaz; özel adlarda yumuşama yazıya yansımaz.", tags: ["ses bilgisi", "yumuşama"], difficulty: "Orta" },
  { id: "tr12", category: "turkce", title: "Ünlü Düşmesi", summary: "İkinci hecesinde dar ünlü bulunan bazı sözcükler ek alınca ünlüsünü düşürür.", detail: "'omuz → omzu', 'burun → burnu', 'nefes → nefsi'. Ayrıca 'sarı+ar → sarar', 'ileri+le → ilerle' gibi türemelerde de görülür.", funFact: "Ünlü düşmesine 'orta hece düşmesi' de denir; hızlı tanımak puan kazandırır.", tags: ["ses bilgisi", "ünlü düşmesi"], difficulty: "Orta" },
  { id: "tr13", category: "turkce", title: "Sözcük Türleri: İsim", summary: "Varlıkları karşılayan sözcüklerdir; özel-cins, somut-soyut, tekil-çoğul olabilir.", detail: "Özel isim tek bir varlığa özgüdür (Ankara). Cins isim türün ortak adıdır (şehir). Somut isim duyularla algılanır, soyut isim algılanamaz (sevgi).", funFact: "Topluluk isimleri (ordu, sürü) tekil görünse de çokluk anlamı taşır.", tags: ["isim", "sözcük türleri"], difficulty: "Temel" },
  { id: "tr14", category: "turkce", title: "Sıfatlar", summary: "İsimleri niteleyen ya da belirten sözcüklerdir: güzel ev, üç kalem.", detail: "Niteleme sıfatları 'nasıl' sorusuna cevap verir (kırmızı gül). Belirtme sıfatları işaret (bu), sayı (beş), soru (kaç), belgisiz (bazı) olarak ayrılır.", funFact: "Sıfat tek başına kullanılırsa adlaşmış sıfat olur: 'Küçükler oynasın.'", tags: ["sıfat", "sözcük türleri"], difficulty: "Orta" },
  { id: "tr15", category: "turkce", title: "Zamirler (Adıllar)", summary: "İsmin yerini geçici olarak tutan sözcüklerdir: ben, bu, kim, kendi.", detail: "Kişi (ben, sen), işaret (bu, şu), belgisiz (biri, herkes), soru (kim, ne) zamirleri vardır. Ek halinde de olabilir: 'kalemim'deki '-im' iyelik zamiridir.", funFact: "'Bu' hem sıfat hem zamir olabilir; isimden önce gelip nitelerse sıfattır.", tags: ["zamir", "sözcük türleri"], difficulty: "Orta" },
  { id: "tr16", category: "turkce", title: "Zarflar (Belirteçler)", summary: "Fiili, sıfatı ya da başka zarfı niteleyen sözcüklerdir: hızlı koştu, çok güzel.", detail: "Durum (nasıl), zaman (ne zaman), yer-yön (nereye), miktar (ne kadar), soru zarfları vardır. Zarflar çekim eki almaz, bu yönüyle isimden ayrılır.", funFact: "'Yavaş' hem sıfat hem zarf olabilir; ismi nitelerse sıfat, fiili nitelerse zarftır.", tags: ["zarf", "sözcük türleri"], difficulty: "Orta" },
  { id: "tr17", category: "turkce", title: "Fiilde Kip ve Zaman", summary: "Haber kipleri zaman bildirir (-di, -miş, -yor, -ecek, -r); dilek kipleri istek bildirir.", detail: "Dilek kipleri: gereklilik (-meli), şart (-se), istek (-e), emir. Haber kipleri: görülen geçmiş, öğrenilen geçmiş, şimdiki, gelecek, geniş zaman.", funFact: "Bir fiil hem kip hem kişi eki alır; 'gelmeliyim' gereklilik kipi + 1. tekil kişi.", tags: ["fiil", "kip", "zaman"], difficulty: "Orta" },
  { id: "tr18", category: "turkce", title: "Fiilimsiler", summary: "Fiilden türeyip cümlede isim, sıfat, zarf görevi yapan sözcüklerdir.", detail: "İsim-fiil (-mek, -ma, -ış): koşmak. Sıfat-fiil (-an, -ası, -mez, -ar, -dik, -ecek, -miş): gelen kişi. Zarf-fiil (-ip, -erek, -ince, -ken): gülerek.", funFact: "Fiilimsi bulunan cümle en az iki yüklem içerir, yani girişik birleşik cümledir.", tags: ["fiilimsi", "cümle bilgisi"], difficulty: "İleri" },
  { id: "tr19", category: "turkce", title: "Cümle Türleri", summary: "Yükleme, öge dizilişine, anlamına ve yapısına göre cümleler sınıflanır.", detail: "Yükleme göre: fiil/isim cümlesi. Diziliş: kurallı/devrik. Yapı: basit, birleşik, sıralı, bağlı. Anlam: olumlu, olumsuz, soru, ünlem.", funFact: "Tek yüklemi olan cümle basittir; fiilimsi de içermez.", tags: ["cümle bilgisi", "cümle türleri"], difficulty: "İleri" },
  { id: "tr20", category: "turkce", title: "Noktalama İşaretleri", summary: "Anlamı belirginleştiren, okumayı kolaylaştıran işaretlerdir.", detail: "Virgül eş görevli sözcükleri ayırır; noktalı virgül anlamca bağlı cümleleri. İki nokta açıklama/örnek öncesi kullanılır. Tırnak alıntıları belirtir.", funFact: "Özneden sonra virgül konmaz; 'Ali, geldi' yanlıştır (Ali özneyse).", tags: ["noktalama", "yazım"], difficulty: "Temel" },
  { id: "tr21", category: "turkce", title: "Anlatım Biçimleri", summary: "Açıklama, tartışma, betimleme ve öyküleme temel anlatım biçimleridir.", detail: "Açıklama bilgi verir. Tartışma karşıt görüş çürütür. Betimleme sözle resim çizer. Öyküleme olayı zaman akışında anlatır.", funFact: "Betimlemede sıfatlar, öykülemede fiiller yoğundur.", tags: ["anlatım biçimi", "paragraf"], difficulty: "Orta" },
  { id: "tr22", category: "turkce", title: "Düşünceyi Geliştirme Yolları", summary: "Tanımlama, örnekleme, tanık gösterme, karşılaştırma, sayısal veri kullanılır.", detail: "Tanık gösterme (alıntı) bir otoritenin sözüyle desteklemedir. Örnekleme somutlaştırır. Sayısal veriler nesnelliği artırır. Benzetme ve karşılaştırma anlamı güçlendirir.", funFact: "'... der ki' ifadesi tanık gösterme, 'örneğin' örneklemedir.", tags: ["paragraf", "düşünceyi geliştirme"], difficulty: "Orta" },
  { id: "tr23", category: "turkce", title: "Paragrafta Yapı", summary: "Giriş bağlaçsız başlar, gelişme örneklerle açar, sonuç toparlar.", detail: "Giriş cümlesi genellikle 'bu, o, ancak, ama' gibi bağlayıcılarla başlamaz. Paragrafı ikiye bölme sorularında konu değişimi aranır.", funFact: "Anlam akışını bozan cümle sorularında konudan sapan cümle işaretlenir.", tags: ["paragraf", "yapı"], difficulty: "Orta" },
  { id: "tr24", category: "turkce", title: "Ek Fiil (Ekeylem)", summary: "İsim soylu sözcükleri yüklem yapar (-dır, -di, -miş, -se) veya basit fiili birleşik zamanlı yapar.", detail: "'Hastayım' → 'hasta' ismine ek fiil gelmiş. 'Geliyordu' → 'geliyor'+'idi' birleşik zamanlı fiil. Ek fiilin dört kipi vardır.", funFact: "Ek fiil çoğu zaman '-dır' bildirme ekiyle gizlidir: 'Yol uzundur.'", tags: ["ek fiil", "dil bilgisi"], difficulty: "İleri" },
  { id: "tr25", category: "turkce", title: "Yapım Ekleri", summary: "Sözcüğün anlamını veya türünü değiştirerek yeni sözcük türetir.", detail: "İsimden isim (-lik: kitaplık), isimden fiil (-le: temizle), fiilden isim (-gi: sevgi), fiilden fiil (-dir: yazdır) yapım ekleri vardır.", funFact: "Yapım eki almış sözcük 'türemiş' sözcüktür; kök + yapım eki = gövde.", tags: ["yapım eki", "sözcük yapısı"], difficulty: "Orta" },

  // ==================== MATEMATİK ====================
  { id: "mat6", category: "matematik", title: "Bölme ve Bölünebilme", summary: "Bir sayı 2'ye son rakamı çift, 3'e rakam toplamı 3'ün katı, 5'e son rakamı 0/5 ise bölünür.", detail: "4'e bölünme: son iki basamak 4'ün katı. 8'e: son üç basamak. 9'a: rakam toplamı 9'un katı. 11'e: dönüşümlü toplam farkı 11'in katı.", funFact: "Bir sayı 6'ya bölünüyorsa hem 2'ye hem 3'e bölünüyordur.", tags: ["bölünebilme", "sayılar"], difficulty: "Temel" },
  { id: "mat7", category: "matematik", title: "EBOB - EKOK", summary: "EBOB en büyük ortak bölen, EKOK en küçük ortak kattır.", detail: "EBOB × EKOK = iki sayının çarpımı. Ortak bölünen problemlerde EKOK, eşit paylaştırmada EBOB kullanılır.", funFact: "Aralarında asal sayıların EBOB'u 1, EKOK'u çarpımlarına eşittir.", tags: ["ebob", "ekok", "sayılar"], difficulty: "Orta" },
  { id: "mat8", category: "matematik", title: "Rasyonel Sayılar", summary: "a/b (b≠0) biçiminde yazılabilen sayılardır; devirli ondalıklar da rasyoneldir.", detail: "Toplama/çıkarmada payda eşitlenir. Çarpmada paylar ve paydalar çarpılır. Bölmede ikinci kesir ters çevrilip çarpılır.", funFact: "0,333... = 1/3 gibi devirli ondalıklar kesir olarak yazılabilir, bu yüzden rasyoneldir.", tags: ["rasyonel", "kesir"], difficulty: "Temel" },
  { id: "mat9", category: "matematik", title: "Üslü Sayılar", summary: "aᵐ·aⁿ=aᵐ⁺ⁿ, aᵐ/aⁿ=aᵐ⁻ⁿ, (aᵐ)ⁿ=aᵐⁿ, a⁰=1.", detail: "Negatif üs terse çevirir: a⁻ⁿ=1/aⁿ. Taban aynıysa üsler işleme girer. (a·b)ⁿ=aⁿ·bⁿ.", funFact: "0⁰ tanımsızdır; sınavda bu tuzağa dikkat et.", tags: ["üslü sayılar", "cebir"], difficulty: "Orta" },
  { id: "mat10", category: "matematik", title: "Köklü Sayılar", summary: "√a·√b=√(ab), √a/√b=√(a/b), √(a²)=|a|.", detail: "Kök dışına çarpan çıkarmada tam kare çarpanlar ayrılır: √12=2√3. Paydayı rasyonel yapmak için eşleniğiyle genişletilir.", funFact: "√(a+b) ≠ √a+√b; bu en sık yapılan hatadır.", tags: ["köklü sayılar", "cebir"], difficulty: "Orta" },
  { id: "mat11", category: "matematik", title: "Oran - Orantı", summary: "a/b=c/d ise a·d=b·c (içler-dışlar çarpımı).", detail: "Doğru orantıda biri artarken diğeri artar (k sabiti). Ters orantıda biri artarken diğeri azalır (çarpımları sabit).", funFact: "'k ile orantılı' ifadesi doğru orantıyı, 'ters orantılı' çarpımın sabitliğini anlatır.", tags: ["oran", "orantı"], difficulty: "Temel" },
  { id: "mat12", category: "matematik", title: "Denklem Çözme", summary: "Bilinmeyeni yalnız bırakmak için eşitliğin iki tarafına aynı işlem uygulanır.", detail: "Birinci dereceden ax+b=0 → x=-b/a. Terimler taraf değiştirirken işaret değişir. Parantezler dağıtılır, benzer terimler toplanır.", funFact: "Bir denklemi kontrol için kökü yerine koy; eşitlik sağlanıyorsa doğrudur.", tags: ["denklem", "cebir"], difficulty: "Temel" },
  { id: "mat13", category: "matematik", title: "İkinci Dereceden Denklemler", summary: "ax²+bx+c=0 için kökler x=(-b±√Δ)/2a, Δ=b²-4ac.", detail: "Δ>0 iki farklı kök, Δ=0 çift katlı kök, Δ<0 gerçek kök yok. Kökler toplamı -b/a, çarpımı c/a.", funFact: "Kökler toplamı ve çarpımını kullanmak, kökleri bulmadan çözüm sağlar.", tags: ["ikinci derece", "denklem"], difficulty: "İleri" },
  { id: "mat14", category: "matematik", title: "Mutlak Değer", summary: "|a| sayının sıfıra uzaklığıdır; daima negatif değildir.", detail: "|x|=a ise x=a veya x=-a. |x|<a ise -a<x<a. Mutlak değerli ifadelerde işaret incelemesi yapılır.", funFact: "|a+b| ≤ |a|+|b| (üçgen eşitsizliği) her zaman geçerlidir.", tags: ["mutlak değer", "cebir"], difficulty: "Orta" },
  { id: "mat15", category: "matematik", title: "Eşitsizlikler", summary: "Negatif sayıyla çarpım/bölümde eşitsizlik yön değiştirir.", detail: "x-2>0 → x>2. -2x>4 → x<-2 (yön döndü). Çözüm kümesi sayı doğrusunda aralık olarak gösterilir.", funFact: "Eşitsizliği negatifle çarpınca yönü çevirmeyi unutmak en yaygın hatadır.", tags: ["eşitsizlik", "cebir"], difficulty: "Orta" },
  { id: "mat16", category: "matematik", title: "Kümeler", summary: "Birleşim (∪), kesişim (∩), fark (\\) ve tümleyen temel işlemlerdir.", detail: "s(A∪B)=s(A)+s(B)-s(A∩B). Boş küme her kümenin alt kümesidir. n elemanlı kümenin 2ⁿ alt kümesi vardır.", funFact: "Alt küme sayısı 2ⁿ, öz alt küme sayısı 2ⁿ-1'dir.", tags: ["küme", "cebir"], difficulty: "Temel" },
  { id: "mat17", category: "matematik", title: "Permütasyon", summary: "n farklı nesnenin r'li sıralı diziliş sayısı P(n,r)=n!/(n-r)!.", detail: "Sıralamanın önemli olduğu durumlarda kullanılır. n nesnenin tamamının dizilişi n!'dir. Dairesel permütasyon (n-1)!'dir.", funFact: "0!=1 kabul edilir; bu tanım formüllerin tutarlılığı içindir.", tags: ["permütasyon", "sayma"], difficulty: "İleri" },
  { id: "mat18", category: "matematik", title: "Kombinasyon", summary: "Sıralamanın önemsiz olduğu seçim sayısı C(n,r)=n!/[r!(n-r)!].", detail: "Gruplama, seçme problemlerinde kullanılır. C(n,r)=C(n,n-r). Permütasyondan farkı sıralama içermemesidir.", funFact: "C(n,0)=C(n,n)=1; hiç seçmemek ve hepsini seçmek birer yoldur.", tags: ["kombinasyon", "sayma"], difficulty: "İleri" },
  { id: "mat19", category: "matematik", title: "Fonksiyon Kavramı", summary: "Her girdiye tek çıktı eşleyen kurala fonksiyon denir.", detail: "Tanım kümesindeki her eleman görüntü kümesinde bir değere gitmelidir. Birebir (farklıya farklı), örten (tüm değer kümesi kaplanır) türleri vardır.", funFact: "Dikey doğru testi: grafiği bir dikey doğru en fazla bir noktada kesiyorsa fonksiyondur.", tags: ["fonksiyon", "cebir"], difficulty: "Orta" },
  { id: "mat20", category: "matematik", title: "Polinomlar", summary: "Değişkenin tam sayı kuvvetlerinden oluşan cebirsel ifadelerdir.", detail: "Derece en büyük üstür. P(a), a'nın polinomdaki değeridir. Bölme algoritması: P(x)=B(x)·Q(x)+K(x). Kalan teoremi: P(x)'in (x-a)'ya kalanı P(a)'dır.", funFact: "P(1) katsayılar toplamını, P(0) sabit terimi verir.", tags: ["polinom", "cebir"], difficulty: "İleri" },
  { id: "mat21", category: "matematik", title: "Logaritma", summary: "log_a b = c ⇔ aᶜ = b. log(xy)=log x+log y.", detail: "log(x/y)=log x - log y. log(xⁿ)=n·log x. Taban değiştirme: log_a b = log b / log a. ln doğal logaritmadır (taban e).", funFact: "log 1 = 0 ve log_a a = 1 her tabanda geçerlidir.", tags: ["logaritma", "AYT"], difficulty: "İleri" },
  { id: "mat22", category: "matematik", title: "Diziler", summary: "Aritmetik dizide fark, geometrik dizide oran sabittir.", detail: "Aritmetik: aₙ=a₁+(n-1)d. Geometrik: aₙ=a₁·rⁿ⁻¹. Aritmetik dizi toplamı n·(a₁+aₙ)/2.", funFact: "Ardışık sayılar toplamı ortadaki terim × terim sayısına eşittir.", tags: ["dizi", "AYT"], difficulty: "İleri" },
  { id: "mat23", category: "matematik", title: "Limit", summary: "Bir noktaya yaklaşırken fonksiyonun yöneldiği değerdir.", detail: "Soldan ve sağdan limit eşitse limit vardır. 0/0 belirsizliğinde çarpanlara ayırma veya sadeleştirme yapılır. Süreklilik için limit = fonksiyon değeri olmalıdır.", funFact: "Limit fonksiyonun o noktadaki değerinden bağımsızdır; nokta tanımsız olsa da limit olabilir.", tags: ["limit", "AYT", "analiz"], difficulty: "İleri" },
  { id: "mat24", category: "matematik", title: "İntegral", summary: "Türevin tersi işlemdir; eğri altındaki alanı hesaplar.", detail: "Belirsiz integral ∫f(x)dx=F(x)+C. Belirli integral iki sınır arasındaki alanı verir: ∫ₐᵇ. Alan hesabı, hacim ve ortalama değer uygulamaları vardır.", funFact: "∫xⁿdx = xⁿ⁺¹/(n+1) + C (n≠-1); türev kuralının tersidir.", tags: ["integral", "AYT", "analiz"], difficulty: "İleri" },
  { id: "mat25", category: "matematik", title: "Trigonometri Temelleri", summary: "sin=karşı/hipotenüs, cos=komşu/hipotenüs, tan=karşı/komşu.", detail: "sin²x+cos²x=1 temel özdeşliktir. Birim çemberde açılar radyan cinsinden ifade edilir (180°=π). Özel açılar 30-45-60'ın değerleri ezberlenmelidir.", funFact: "tan x = sin x / cos x; cos x=0 olduğunda tan tanımsızdır.", tags: ["trigonometri", "AYT"], difficulty: "İleri" },
  { id: "mat26", category: "matematik", title: "Basit Faiz - Yüzde", summary: "Yüzde: bir bütünün 100'e bölünmüş parçasıdır. Faiz = Anapara×n×t/100.", detail: "%20 artış 1,2 ile çarpma demektir. Ardışık yüzde değişimlerde doğrudan toplama yapılmaz. Karışım problemlerinde bileşen oranları korunur.", funFact: "%20 artıp %20 azalan sayı eski haline dönmez, %4 azalır.", tags: ["yüzde", "problem"], difficulty: "Orta" },

  // ==================== GEOMETRİ ====================
  { id: "geo4", category: "geometri", title: "Açılar", summary: "Tümler açılar 90°, bütünler açılar 180° toplar.", detail: "Ters açılar eşittir. Paralel iki doğruyu kesen doğruda yöndeş, iç ters, dış ters açılar eşittir. Komşu bütünler açılar bir doğru oluşturur.", funFact: "Bir noktada oluşan açıların toplamı 360°'dir.", tags: ["açı", "temel geometri"], difficulty: "Temel" },
  { id: "geo5", category: "geometri", title: "Üçgende Açı-Kenar Bağıntısı", summary: "Büyük açının karşısında büyük kenar bulunur.", detail: "İç açılar toplamı 180°, dış açılar toplamı 360°. Bir dış açı, komşu olmayan iki iç açının toplamına eşittir. Üçgen eşitsizliği: bir kenar diğer ikisinin farkı ile toplamı arasındadır.", funFact: "İki kenarı verilen üçgenin üçüncü kenarı, farkla toplam arasında olmalıdır.", tags: ["üçgen", "açı"], difficulty: "Orta" },
  { id: "geo6", category: "geometri", title: "Üçgende Eşlik ve Benzerlik", summary: "Eş üçgenler tıpatıp aynı, benzer üçgenler aynı biçimde farklı boyuttadır.", detail: "Benzerlikte açılar eşit, kenarlar orantılıdır (AA, KKK, KAK). Benzerlik oranı k ise alan oranı k²'dir. Eşlik durumları: KKK, KAK, AKA.", funFact: "Benzer üçgenlerde alan oranı, kenar oranının karesidir; hacimde küpüdür.", tags: ["benzerlik", "üçgen"], difficulty: "İleri" },
  { id: "geo7", category: "geometri", title: "Üçgende Açıortay", summary: "İç açıortay karşı kenarı komşu kenarlarla orantılı böler.", detail: "İç açıortayların kesişimi iç teğet çemberin merkezidir (iç merkez). Açıortay üzerindeki her nokta açının kollarına eşit uzaklıktadır.", funFact: "İç merkez, üçgenin içine çizilen çemberin merkezidir.", tags: ["açıortay", "üçgen"], difficulty: "İleri" },
  { id: "geo8", category: "geometri", title: "Üçgende Kenarortay", summary: "Kenarortaylar ağırlık merkezinde 2:1 oranında kesişir.", detail: "Ağırlık merkezi her kenarortayı köşeden 2, kenardan 1 birim olacak şekilde böler. Kenarortay üçgeni iki eşit alana böler.", funFact: "Bir kenarortay üçgenin alanını daima iki eşit parçaya böler.", tags: ["kenarortay", "üçgen"], difficulty: "İleri" },
  { id: "geo9", category: "geometri", title: "Dörtgenler", summary: "Dörtgende iç açılar toplamı 360°'dir.", detail: "Paralelkenarda karşılıklı kenarlar ve açılar eşittir. Dikdörtgen köşegenleri eşit, eşkenar dörtgen köşegenleri diktir. Kare hepsinin özelliklerini taşır.", funFact: "Köşegenleri hem eşit hem birbirini dik ortalayan tek dörtgen karedir.", tags: ["dörtgen", "geometri"], difficulty: "Orta" },
  { id: "geo10", category: "geometri", title: "Çokgenler", summary: "n kenarlı çokgende iç açılar toplamı (n-2)·180°'dir.", detail: "Dış açılar toplamı her zaman 360°'dir. Düzgün çokgende bir iç açı (n-2)·180/n. Köşegen sayısı n(n-3)/2.", funFact: "Düzgün çokgenin dış açısı 360/n ile kolayca bulunur.", tags: ["çokgen", "geometri"], difficulty: "Orta" },
  { id: "geo11", category: "geometri", title: "Çemberde Uzunluk ve Alan", summary: "Çevre 2πr, daire alanı πr². Yay uzunluğu ve daire dilimi açıyla orantılıdır.", detail: "Merkez açısı α olan yay uzunluğu (α/360)·2πr, daire dilimi alanı (α/360)·πr². Kirişin uzaklığı Pisagor ile bulunur.", funFact: "Yarım çemberin alanı πr²/2, çeyreğin πr²/4'tür.", tags: ["çember", "alan"], difficulty: "Orta" },
  { id: "geo12", category: "geometri", title: "Katı Cisimler: Prizma", summary: "Hacim = taban alanı × yükseklik.", detail: "Dik prizmada yüzey alanı = 2×taban + yanal alan. Küpün hacmi a³, yüzeyi 6a². Dikdörtgenler prizmasının hacmi a·b·c.", funFact: "Kürenin hacmi (4/3)πr³, yüzey alanı 4πr²'dir.", tags: ["katı cisim", "hacim"], difficulty: "İleri" },
  { id: "geo13", category: "geometri", title: "Analitik Geometri: Doğru", summary: "İki nokta arası uzaklık √[(x₂-x₁)²+(y₂-y₁)²]. Eğim m=Δy/Δx.", detail: "Doğru denklemi y=mx+n. Paralel doğruların eğimleri eşit, dik doğruların eğimleri çarpımı -1'dir. Orta nokta koordinatların ortalamasıdır.", funFact: "Yatay doğrunun eğimi 0, dikey doğrunun eğimi tanımsızdır.", tags: ["analitik", "doğru"], difficulty: "İleri" },
  { id: "geo14", category: "geometri", title: "Analitik: Çember Denklemi", summary: "Merkezi (a,b), yarıçapı r olan çember: (x-a)²+(y-b)²=r².", detail: "Merkezi orijinde ise x²+y²=r². Genel denklem x²+y²+Dx+Ey+F=0 biçimindedir. Yarıçap ve merkez tamamlama ile bulunur.", funFact: "Denklemde x² ve y² katsayıları eşit ve xy terimi yoksa şekil çemberdir.", tags: ["analitik", "çember"], difficulty: "İleri" },
  { id: "geo15", category: "geometri", title: "Dönüşüm Geometrisi", summary: "Öteleme, yansıma ve dönme temel dönüşümlerdir.", detail: "x eksenine yansımada y işaret değiştirir, y eksenine yansımada x. Öteleme koordinatlara sabit ekler. Dönme açıya göre koordinatları değiştirir.", funFact: "Yansıma ve dönme şeklin boyutunu değiştirmez, yalnızca konumunu.", tags: ["dönüşüm", "analitik"], difficulty: "Orta" },

  // ==================== FİZİK ====================
  { id: "fiz4", category: "fizik", title: "Vektörler", summary: "Hem büyüklüğü hem yönü olan niceliklerdir: kuvvet, hız, ivme.", detail: "Skaler nicelikler yalnız büyüklük taşır (kütle, sıcaklık). Vektörler uç uca eklenerek veya paralelkenar yöntemiyle toplanır. Bileşenlerine ayrılabilir.", funFact: "Aynı doğrultuda zıt yönlü eşit vektörlerin bileşkesi sıfırdır.", tags: ["vektör", "temel"], difficulty: "Orta" },
  { id: "fiz5", category: "fizik", title: "Bağıl Hareket", summary: "Bir cismin hareketi, gözlemcinin referans noktasına göre değişir.", detail: "İki aracın bağıl hızı, aynı yönde farkları, zıt yönde toplamları alınarak bulunur. Yağmurun eğik görünmesi bağıl hareketin sonucudur.", funFact: "Yan yana aynı hızla giden iki araç birbirine göre duruyor gibidir.", tags: ["bağıl hareket", "hareket"], difficulty: "Orta" },
  { id: "fiz6", category: "fizik", title: "Sabit İvmeli Hareket", summary: "v=v₀+at, x=v₀t+½at², v²=v₀²+2ax.", detail: "İvme hızın zamanla değişimidir. Serbest düşmede a=g≈10 m/s². Hız-zaman grafiğinin altındaki alan yol verir; eğimi ivmedir.", funFact: "Serbest düşen cisim ardışık saniyelerde 1:3:5:7 oranında yol alır.", tags: ["hareket", "ivme"], difficulty: "İleri" },
  { id: "fiz7", category: "fizik", title: "İtme ve Momentum", summary: "Momentum p=m·v. İtme = kuvvet × zaman = momentum değişimi.", detail: "Çarpışmalarda toplam momentum korunur. Esnek çarpışmada kinetik enerji de korunur, esnek olmayan çarpışmada korunmaz.", funFact: "Airbag ve emniyet kemeri, çarpışma süresini uzatarak kuvveti azaltır.", tags: ["momentum", "itme"], difficulty: "İleri" },
  { id: "fiz8", category: "fizik", title: "Basınç", summary: "Katı basıncı P=F/A, sıvı basıncı P=h·d·g.", detail: "Sıvı basıncı derinliğe ve yoğunluğa bağlıdır, kabın şekline değil. Gaz basıncı her yöne eşit iletilir (Pascal). Açık hava basıncı barometre ile ölçülür.", funFact: "Sıvı basıncı yalnızca derinliğe bağlıdır; kabın genişliği etkilemez.", tags: ["basınç", "akışkan"], difficulty: "Orta" },
  { id: "fiz9", category: "fizik", title: "Kaldırma Kuvveti", summary: "Arşimet: bir cisme etkiyen kaldırma kuvveti taşırdığı sıvının ağırlığına eşittir.", detail: "F_kaldırma = V_batan · d_sıvı · g. Cisim yoğunluğu sıvıdan azsa yüzer, fazlaysa batar, eşitse askıda kalır.", funFact: "Buzdağının yalnızca yaklaşık %10'u su üstünde görünür.", tags: ["kaldırma kuvveti", "arşimet"], difficulty: "Orta" },
  { id: "fiz10", category: "fizik", title: "Isı ve Sıcaklık", summary: "Isı enerjidir (joule), sıcaklık ise moleküllerin ortalama kinetik enerjisidir.", detail: "Q=m·c·ΔT. Hal değişiminde sıcaklık sabit kalır, gizli ısı alınır/verilir. Isı yüksekten düşük sıcaklığa akar.", funFact: "Suyun öz ısısı yüksektir; bu yüzden denizler sıcaklığı dengeler.", tags: ["ısı", "sıcaklık"], difficulty: "Orta" },
  { id: "fiz11", category: "fizik", title: "Işık ve Gölge", summary: "Işık doğrusal yol izler; opak cisimler gölge oluşturur.", detail: "Tam gölge (umbra) ışığın hiç ulaşmadığı, yarı gölge ışığın kısmen ulaştığı bölgedir. Ay ve Güneş tutulmaları gölge olayıdır.", funFact: "Güneş tutulması Ay Dünya ile Güneş arasına girdiğinde oluşur.", tags: ["ışık", "gölge", "optik"], difficulty: "Temel" },
  { id: "fiz12", category: "fizik", title: "Aynalar", summary: "Düz aynada görüntü sanal ve simetriktir; küresel aynalar odaklar.", detail: "Çukur ayna cisim uzaktayken gerçek görüntü verir. Tümsek ayna daima küçük, sanal, düz görüntü verir. Odak uzaklığı yarıçapın yarısıdır.", funFact: "Araç yan aynaları tümsek aynadır; daha geniş görüş açısı sağlar.", tags: ["ayna", "optik"], difficulty: "Orta" },
  { id: "fiz13", category: "fizik", title: "Mercekler ve Kırılma", summary: "Işık farklı ortama geçerken hız değiştirir ve kırılır.", detail: "Yakınsak (ince kenarlı) mercek ışığı toplar, ıraksak (kalın kenarlı) dağıtır. Kırılma indisi büyük ortamda ışık yavaşlar. Tam yansıma kritik açının üstünde olur.", funFact: "Suya batan çubuğun kırık görünmesi ışığın kırılmasındandır.", tags: ["mercek", "kırılma", "optik"], difficulty: "İleri" },
  { id: "fiz14", category: "fizik", title: "Elektrostatik", summary: "Aynı yükler iter, zıt yükler çeker. Yük korunur.", detail: "Coulomb yasası: F=k·q₁·q₂/d². Cisimler sürtünme, dokunma veya etki ile yüklenir. İletkende yük yüzeye dağılır.", funFact: "Kışın kapı koluna dokununca çarpılma statik elektrik boşalmasıdır.", tags: ["elektrik", "yük"], difficulty: "İleri" },
  { id: "fiz15", category: "fizik", title: "Mıknatıslar ve Manyetizma", summary: "Mıknatısın iki kutbu vardır ve ayrılamaz.", detail: "Aynı kutuplar iter, zıt kutuplar çeker. Akım geçen tel çevresinde manyetik alan oluşur. Dünya dev bir mıknatıs gibi davranır, pusula bu yüzden yön gösterir.", funFact: "Bir mıknatıs ortadan kırılırsa yine iki kutuplu iki mıknatıs oluşur.", tags: ["manyetizma", "mıknatıs"], difficulty: "Orta" },
  { id: "fiz16", category: "fizik", title: "Dalgalar", summary: "Dalga enerjiyi madde taşımadan iletir. v=λ·f.", detail: "Boyuna dalgada titreşim yayılma ile aynı yönde (ses), enine dalgada dik (su, ışık). Genlik enerjiyle, frekans periyotla ilişkilidir.", funFact: "Ses boyuna, ışık enine dalgadır; ışık boşlukta da yayılır.", tags: ["dalga", "titreşim"], difficulty: "Orta" },
  { id: "fiz17", category: "fizik", title: "Modern Fizik: Fotoelektrik", summary: "Işık, metalden elektron kopardığında fotoelektrik olay gerçekleşir.", detail: "Einstein, ışığın foton adı verilen enerji paketlerinden oluştuğunu gösterdi. Elektron kopması ışığın şiddetine değil frekansına bağlıdır.", funFact: "Einstein Nobel'i görelilikten değil, fotoelektrik olayı açıkladığı için aldı.", tags: ["modern fizik", "foton"], difficulty: "İleri" },

  // ==================== KİMYA ====================
  { id: "kim4", category: "kimya", title: "Atomun Yapısı", summary: "Atom; proton, nötron (çekirdek) ve elektronlardan oluşur.", detail: "Proton sayısı atom numarasını (element kimliğini) belirler. Kütle numarası proton+nötron. İzotoplar aynı proton, farklı nötron sayısına sahiptir.", funFact: "Atomun kütlesinin neredeyse tamamı çok küçük çekirdekte toplanmıştır.", tags: ["atom", "yapı"], difficulty: "Temel" },
  { id: "kim5", category: "kimya", title: "Elektron Dizilimi", summary: "Elektronlar enerji seviyelerine (orbitallere) belirli kurallarla yerleşir.", detail: "Aufbau ilkesine göre düşük enerjili orbitaller önce dolar. Değerlik elektronları en dış katmandadır ve kimyasal davranışı belirler.", funFact: "Bir elementin grup numarası çoğunlukla değerlik elektron sayısını verir.", tags: ["elektron", "dizilim"], difficulty: "İleri" },
  { id: "kim6", category: "kimya", title: "Kimyasal Bağlar", summary: "İyonik bağ elektron alışverişi, kovalent bağ elektron paylaşımıdır.", detail: "Metal-ametal arasında iyonik, ametal-ametal arasında kovalent bağ oluşur. Metaller arası metalik bağ bulunur. Polar/apolar kovalent elektronegatiflik farkına bağlıdır.", funFact: "Tuz (NaCl) iyonik, su (H₂O) polar kovalent bağ içerir.", tags: ["bağ", "kimya"], difficulty: "Orta" },
  { id: "kim7", category: "kimya", title: "Bileşikler ve Formüller", summary: "İki veya daha çok elementin belirli oranda birleşmesiyle bileşik oluşur.", detail: "Değerliklere göre formül yazılır (çapraz kural). Bileşiğin özellikleri onu oluşturan elementlerden tamamen farklıdır.", funFact: "Sodyum patlayıcı, klor zehirlidir; birleşince yenilebilir tuz oluşur.", tags: ["bileşik", "formül"], difficulty: "Orta" },
  { id: "kim8", category: "kimya", title: "Kimyasal Tepkimeler", summary: "Girenler ürünlere dönüşür; atom sayısı iki tarafta eşit olmalıdır (denkleştirme).", detail: "Yanma, sentez, analiz, yer değiştirme tepkime türleridir. Kütle korunur (Lavoisier). Katsayılar denkleştirme için kullanılır.", funFact: "Bir tepkimede atomlar yok olmaz, yalnızca yeniden düzenlenir.", tags: ["tepkime", "denkleştirme"], difficulty: "Orta" },
  { id: "kim9", category: "kimya", title: "Karışımlar", summary: "Homojen karışımlar (çözelti) her yerde aynı, heterojen karışımlar farklıdır.", detail: "Ayırma yöntemleri: buharlaştırma, damıtma, süzme, mıknatısla ayırma, ayırma hunisi. Karışımda bileşenler kimyasal özelliğini korur.", funFact: "Hava homojen bir gaz karışımıdır; çözelti sayılır.", tags: ["karışım", "ayırma"], difficulty: "Temel" },
  { id: "kim10", category: "kimya", title: "Çözünürlük", summary: "Bir maddenin çözücüde çözünebilme miktarıdır; sıcaklık ve basınçla değişir.", detail: "Katıların çözünürlüğü genelde sıcaklıkla artar. Gazların çözünürlüğü sıcaklıkla azalır, basınçla artar. 'Benzer benzeri çözer' kuralı geçerlidir.", funFact: "Gazlı içecek açılınca köpürür çünkü basınç düşünce gaz çözünürlüğü azalır.", tags: ["çözünürlük", "çözelti"], difficulty: "Orta" },
  { id: "kim11", category: "kimya", title: "Maddenin Halleri", summary: "Katı, sıvı, gaz ve plazma; tanecikler arası çekim ve enerjiyle belirlenir.", detail: "Hal değişimleri: erime, donma, buharlaşma, yoğuşma, süblimleşme. Hal değişimi sırasında sıcaklık sabit kalır; enerji tanecik düzenini değiştirir.", funFact: "Naftalin ve kuru buz sıvı hale geçmeden doğrudan gaz olur (süblimleşme).", tags: ["madde", "hal değişimi"], difficulty: "Temel" },
  { id: "kim12", category: "kimya", title: "Asit-Baz Tepkimeleri", summary: "Asit + baz → tuz + su (nötrleşme).", detail: "Kuvvetli asit-baz tam iyonlaşır. Turnusol asitte kırmızı, bazda mavidir. pH<7 asidik, pH=7 nötr, pH>7 baziktir.", funFact: "Mide ekşimesinde alınan antasitler bazdır; fazla asidi nötrleştirir.", tags: ["asit", "baz", "nötrleşme"], difficulty: "Orta" },
  { id: "kim13", category: "kimya", title: "Organik Kimya: Hidrokarbonlar", summary: "Yalnızca karbon ve hidrojenden oluşan bileşiklerdir.", detail: "Alkanlar tekli bağ (CₙH₂ₙ₊₂), alkenler ikili, alkinler üçlü bağ içerir. Karbon dört bağ yapabildiği için çok çeşitli bileşik oluşur.", funFact: "Metan (CH₄) en basit hidrokarbon ve doğal gazın ana bileşenidir.", tags: ["organik", "hidrokarbon"], difficulty: "İleri" },
  { id: "kim14", category: "kimya", title: "Gazların Genel Özellikleri", summary: "Gazlar bulundukları kabı tümüyle doldurur ve sıkıştırılabilir.", detail: "PV=nRT ideal gaz denklemidir. Sabit sıcaklıkta basınç-hacim ters orantılıdır (Boyle). Sabit basınçta hacim-sıcaklık doğru orantılıdır (Charles).", funFact: "Sıcaklık arttıkça gaz molekülleri hızlanır, basınç artar.", tags: ["gaz", "ideal gaz"], difficulty: "İleri" },
  { id: "kim15", category: "kimya", title: "Kimya Her Yerde", summary: "Temizlik, gıda, ilaç ve endüstride kimya bilgisi kullanılır.", detail: "Sabun ve deterjanlar yağı suda çözer. Polimerler (plastik) küçük birimlerin tekrarıyla oluşur. Yükseltgenme-indirgenme paslanmayı açıklar.", funFact: "Sabun molekülünün bir ucu suyu, diğer ucu yağı sever; kiri böyle söker.", tags: ["günlük kimya", "uygulama"], difficulty: "Temel" },

  // ==================== BİYOLOJİ ====================
  { id: "biyo4", category: "biyoloji", title: "Canlıların Ortak Özellikleri", summary: "Beslenme, solunum, boşaltım, üreme, hareket, uyarılara tepki ortak özelliklerdir.", detail: "Tüm canlılar hücrelerden oluşur, metabolizma yürütür ve homeostazı korur. Büyüme, gelişme ve organizasyon da ortak özelliklerdendir.", funFact: "Virüsler hücresel yapıya sahip olmadığından cansız-canlı arası kabul edilir.", tags: ["canlılık", "ortak özellik"], difficulty: "Temel" },
  { id: "biyo5", category: "biyoloji", title: "Organik Bileşikler", summary: "Karbonhidrat, lipit, protein ve nükleik asit temel organik moleküllerdir.", detail: "Karbonhidratlar enerji verir. Lipitler enerji depolar ve zar yapar. Proteinler yapı ve enzim görevi görür. Nükleik asitler kalıtımı taşır.", funFact: "Enzimler protein yapılıdır ve tepkimeleri hızlandırır ama kendisi değişmez.", tags: ["organik", "biyomolekül"], difficulty: "Orta" },
  { id: "biyo6", category: "biyoloji", title: "Enzimler", summary: "Biyolojik katalizörlerdir; tepkimeleri hızlandırır, aktivasyon enerjisini düşürür.", detail: "Anahtar-kilit modeliyle substrata özgüdür. Sıcaklık, pH ve substrat derişiminden etkilenir. Yüksek sıcaklıkta yapısı bozulur (denatürasyon).", funFact: "Ateş yükseldiğinde enzimler bozulabildiği için vücut için tehlikelidir.", tags: ["enzim", "metabolizma"], difficulty: "İleri" },
  { id: "biyo7", category: "biyoloji", title: "Hücre Zarından Madde Geçişi", summary: "Pasif taşıma enerji istemez, aktif taşıma ATP harcar.", detail: "Difüzyon çoktan aza doğrudur. Osmoz suyun yarı geçirgen zardan geçişidir. Aktif taşıma azdan çoğa, enerji harcayarak olur.", funFact: "Salatalığa tuz dökülünce su kaybetmesi osmozla açıklanır.", tags: ["hücre zarı", "taşıma"], difficulty: "Orta" },
  { id: "biyo8", category: "biyoloji", title: "Mitoz Bölünme", summary: "Bir hücreden genetik olarak özdeş iki hücre oluşur.", detail: "Büyüme, onarım ve eşeysiz üremeyi sağlar. Kromozom sayısı korunur (2n→2n). Evreleri: profaz, metafaz, anafaz, telofaz.", funFact: "Yaralarımızın iyileşmesi ve kestiğimiz saçın uzaması mitozla olur.", tags: ["mitoz", "hücre bölünmesi"], difficulty: "Orta" },
  { id: "biyo9", category: "biyoloji", title: "Mayoz Bölünme", summary: "Kromozom sayısını yarıya indirir; üreme hücreleri (gamet) oluşturur.", detail: "2n hücreden dört adet n hücre oluşur. Cross-over (parça değişimi) çeşitlilik sağlar. Türlerin kromozom sayısının sabit kalmasını sağlar.", funFact: "Mayozdaki parça değişimi kardeşlerin birbirinden farklı olmasının nedenidir.", tags: ["mayoz", "üreme"], difficulty: "İleri" },
  { id: "biyo10", category: "biyoloji", title: "Kalıtım Terimleri", summary: "Gen, alel, genotip, fenotip, homozigot, heterozigot kalıtımın temel kavramlarıdır.", detail: "Genotip genetik yapı, fenotip dış görünüştür. Baskın alel çekiniği örter. Saf döl homozigot, melez heterozigottur.", funFact: "Fenotip = genotip + çevre; aynı genotip farklı çevrede farklı görünebilir.", tags: ["kalıtım", "genetik"], difficulty: "Orta" },
  { id: "biyo11", category: "biyoloji", title: "DNA ve Protein Sentezi", summary: "DNA'daki bilgi RNA'ya kopyalanır (transkripsiyon), proteine çevrilir (translasyon).", detail: "DNA çift zincir, RNA tek zincirdir. Kodon üçlü baz dizisidir ve bir amino asidi belirler. Ribozomda protein sentezlenir.", funFact: "Genetik şifre neredeyse tüm canlılarda ortaktır; evrimin kanıtlarındandır.", tags: ["dna", "protein sentezi"], difficulty: "İleri" },
  { id: "biyo12", category: "biyoloji", title: "Ekosistem ve Besin Zinciri", summary: "Üreticiler, tüketiciler ve ayrıştırıcılar arasında enerji akışı olur.", detail: "Enerji güneşten üreticilere, oradan tüketicilere akar. Her basamakta enerjinin yaklaşık %90'ı kaybolur. Madde döngüleri (su, karbon, azot) sürekli devreder.", funFact: "Enerji tek yönlü akar ama madde ekosistemde sürekli geri dönüşür.", tags: ["ekosistem", "besin zinciri"], difficulty: "Orta" },
  { id: "biyo13", category: "biyoloji", title: "Sınıflandırma (Sistematik)", summary: "Canlılar âlem, şube, sınıf, takım, familya, cins, tür olarak sınıflanır.", detail: "En küçük sınıflandırma birimi türdür. İkili adlandırmada cins+tür kullanılır (Homo sapiens). Benzer canlılar aynı gruba konur.", funFact: "Tür, birbiriyle çiftleşip verimli döl verebilen canlılar topluluğudur.", tags: ["sınıflandırma", "sistematik"], difficulty: "Orta" },
  { id: "biyo14", category: "biyoloji", title: "Sinir Sistemi", summary: "Merkezi (beyin, omurilik) ve çevresel sinir sistemi vücudu yönetir.", detail: "Nöron sinir hücresidir; uyarıyı elektriksel iletir. Refleks omurilikten geçen hızlı tepkidir. Beyin bilinç ve istemli hareketleri kontrol eder.", funFact: "Sıcak sobaya değince elimizi ani çekmemiz omurilik refleksidir, beyin sonradan haberdar olur.", tags: ["sinir sistemi", "nöron"], difficulty: "İleri" },
  { id: "biyo15", category: "biyoloji", title: "Boşaltım ve Dolaşım", summary: "Böbrekler kanı süzer; kalp ve damarlar kanı dolaştırır.", detail: "Nefron böbreğin işlev birimidir. Atardamar kanı kalpten uzaklaştırır, toplardamar kalbe getirir. Büyük ve küçük kan dolaşımı vardır.", funFact: "Böbrekler günde yaklaşık 180 litre kanı süzer ama çoğu suyu geri emer.", tags: ["boşaltım", "dolaşım"], difficulty: "Orta" },

  // ==================== TARİH ====================
  { id: "tar4", category: "tarih", title: "Tarih Öncesi Çağlar", summary: "Taş, Kalkolitik, Tunç ve Demir çağları yazının icadına kadar sürer.", detail: "Yazının bulunmasıyla (MÖ 3200 Sümerler) tarih çağları başlar. Cilalı Taş Devri'nde yerleşik hayata geçildi, tarım ve hayvancılık başladı.", funFact: "Çatalhöyük ve Göbeklitepe, Anadolu'nun en eski yerleşimlerindendir.", tags: ["tarih öncesi", "çağlar"], difficulty: "Temel" },
  { id: "tar5", category: "tarih", title: "İlk Uygarlıklar", summary: "Mezopotamya, Mısır, Anadolu ve Ege'de ilk uygarlıklar doğdu.", detail: "Sümerler yazıyı, Babilliler ilk yazılı kanunları (Hammurabi) buldu. Mısırlılar takvim ve geometride ilerledi. Hititler Anadolu'da güçlü bir devlet kurdu.", funFact: "İlk yazılı antlaşma olan Kadeş, Hititler ile Mısırlılar arasında imzalandı.", tags: ["ilk uygarlıklar", "genel tarih"], difficulty: "Orta" },
  { id: "tar6", category: "tarih", title: "İslamiyet Öncesi Türk Kültürü", summary: "Göçebe yaşam, boylar birliği, töre ve kağanlık yönetim biçimidir.", detail: "Ekonomileri hayvancılığa dayanır. Kut anlayışıyla yönetme yetkisinin Tanrı'dan geldiğine inanılırdı. Gök Tanrı inancı yaygındı.", funFact: "'Kut' anlayışı hükümdarlığın tüm hanedan üyelerine ait olduğu düşüncesini doğurmuş, taht kavgalarına yol açmıştır.", tags: ["türk kültürü", "kağanlık"], difficulty: "Orta" },
  { id: "tar7", category: "tarih", title: "İlk Türk-İslam Devletleri", summary: "Karahanlılar, Gazneliler ve Büyük Selçuklular öne çıkar.", detail: "Karahanlılar İslamiyet'i kabul eden ilk Türk devletidir. Selçuklular Malazgirt Zaferi (1071) ile Anadolu'nun kapılarını Türklere açtı.", funFact: "Karahanlılar resmî dil olarak Türkçeyi kullanan ilk Türk-İslam devletidir.", tags: ["türk-islam", "selçuklu"], difficulty: "Orta" },
  { id: "tar8", category: "tarih", title: "Osmanlı Yükselme Dönemi", summary: "İstanbul'un Fethi'nden (1453) Sokullu'nun ölümüne kadar sürer.", detail: "Fatih İstanbul'u alarak çağ değiştirdi. Yavuz halifeliği Osmanlı'ya getirdi. Kanuni döneminde devlet en geniş sınırlarına ulaştı.", funFact: "1453 İstanbul'un Fethi, Orta Çağ'ı bitirip Yeni Çağ'ı başlatan olay kabul edilir.", tags: ["osmanlı", "yükselme"], difficulty: "Orta" },
  { id: "tar9", category: "tarih", title: "Osmanlı Duraklama ve Gerileme", summary: "Karlofça Antlaşması (1699) ilk büyük toprak kaybıdır.", detail: "Duraklamanın nedenleri: merkezi otoritenin zayıflaması, ekonomik bozulma, askeri gerileme. Lale Devri'nde Batı'ya açılım ve ilk matbaa görülür.", funFact: "İlk Türk matbaası Lale Devri'nde İbrahim Müteferrika tarafından kuruldu.", tags: ["osmanlı", "duraklama"], difficulty: "Orta" },
  { id: "tar10", category: "tarih", title: "Osmanlı'da Yenileşme (Tanzimat)", summary: "Tanzimat Fermanı (1839) hukuk ve yönetimde Batılılaşmayı başlattı.", detail: "Islahat Fermanı (1856) gayrimüslimlere eşitlik getirdi. I. ve II. Meşrutiyet ile anayasal düzene geçildi. Kanun-i Esasi ilk anayasadır.", funFact: "Kanun-i Esasi (1876), Osmanlı'nın ve Türk tarihinin ilk yazılı anayasasıdır.", tags: ["tanzimat", "meşrutiyet"], difficulty: "İleri" },
  { id: "tar11", category: "tarih", title: "I. Dünya Savaşı ve Osmanlı", summary: "Osmanlı, İttifak Devletleri yanında savaşa girdi ve birçok cephede çarpıştı.", detail: "Çanakkale Cephesi'nde büyük zafer kazanıldı. Mondros Ateşkesi (1918) ile fiilen yenilgi kabul edildi ve işgaller başladı.", funFact: "Çanakkale Savaşı, Mustafa Kemal'in askeri dehasını ortaya çıkaran cephedir.", tags: ["I. dünya savaşı", "çanakkale"], difficulty: "Orta" },
  { id: "tar12", category: "tarih", title: "Milli Mücadele Hazırlık Dönemi", summary: "Kongreler ve genelgelerle milli birlik sağlandı.", detail: "Amasya Genelgesi ilk kez milletin bağımsızlığını milletin azmiyle kurtaracağını duyurdu. Erzurum ve Sivas Kongreleri milli birliği kurdu. Misak-ı Milli sınırları belirledi.", funFact: "Amasya Genelgesi, Kurtuluş Savaşı'nın gerekçe, amaç ve yöntemini açıklayan ilk belgedir.", tags: ["milli mücadele", "kongreler"], difficulty: "İleri" },
  { id: "tar13", category: "tarih", title: "Atatürk İlke ve İnkılapları", summary: "Cumhuriyetçilik, milliyetçilik, halkçılık, devletçilik, laiklik, inkılapçılık temel ilkelerdir.", detail: "Saltanat (1922) ve halifelik (1924) kaldırıldı. Harf, kılık-kıyafet, ölçü ve takvim inkılapları yapıldı. Cumhuriyet 1923'te ilan edildi.", funFact: "Laiklik, din ve devlet işlerinin ayrılması ilkesidir; 1937'de anayasaya girdi.", tags: ["inkılap", "atatürk ilkeleri"], difficulty: "Orta" },
  { id: "tar14", category: "tarih", title: "II. Dünya Savaşı", summary: "1939-1945 arası yaşanan, Türkiye'nin savaş dışı kalmayı başardığı büyük savaş.", detail: "Mihver (Almanya, İtalya, Japonya) ile Müttefikler (İngiltere, SSCB, ABD) karşı karşıya geldi. Savaş atom bombasıyla sona erdi. Türkiye savaşa fiilen katılmadı.", funFact: "Türkiye savaşın sonlarında sembolik olarak Almanya ve Japonya'ya savaş ilan etti.", tags: ["II. dünya savaşı", "çağdaş tarih"], difficulty: "Orta" },
  { id: "tar15", category: "tarih", title: "İnkılap: Eğitim ve Kültür", summary: "Tevhid-i Tedrisat ile eğitim birleştirildi, Latin harfleri kabul edildi.", detail: "1924 Öğretim Birliği Kanunu tüm okulları Milli Eğitim'e bağladı. 1928 Harf İnkılabı okuryazarlığı artırdı. TDK ve TTK kuruldu.", funFact: "Harf İnkılabı sonrası açılan Millet Mektepleri ile yetişkinlere okuma yazma öğretildi.", tags: ["inkılap", "eğitim"], difficulty: "Orta" },

  // ==================== COĞRAFYA ====================
  { id: "cog4", category: "cografya", title: "Dünya'nın Şekli ve Hareketleri", summary: "Dünya günlük döner (gece-gündüz), yıllık döner (mevsimler).", detail: "Eksen eğikliği (23°27') mevsimlerin nedenidir. Günlük hareket gece-gündüzü, yerel saat farklarını oluşturur. Yıllık hareket mevsimleri doğurur.", funFact: "Eksen eğik olmasaydı mevsimler oluşmaz, her yer yıl boyu aynı iklime sahip olurdu.", tags: ["dünya", "hareketler"], difficulty: "Orta" },
  { id: "cog5", category: "cografya", title: "Paralel ve Meridyenler", summary: "Paraleller enlemi, meridyenler boylamı gösterir.", detail: "Ekvator 0° paralel, başlangıç meridyeni Greenwich'tir. İki meridyen arası 4 dakikalık zaman farkı vardır. Paraleller arası uzaklık her yerde eşittir (111 km).", funFact: "Aynı meridyen üzerindeki tüm noktalarda yerel saat aynıdır.", tags: ["paralel", "meridyen", "koordinat"], difficulty: "Orta" },
  { id: "cog6", category: "cografya", title: "Yer Şekilleri (İç Kuvvetler)", summary: "Volkanizma, depremler ve orojenez iç kuvvetlerdir; yer kabuğunu şekillendirir.", detail: "İç kuvvetler enerjisini yerin içinden alır ve yükselti oluşturur. Dağ oluşumu (orojenez), kıta oluşumu (epirojenez) ve depremler bu grubtadır.", funFact: "Türkiye deprem kuşağında yer alır çünkü Anadolu levhası sıkışma bölgesindedir.", tags: ["yer şekilleri", "iç kuvvetler"], difficulty: "Orta" },
  { id: "cog7", category: "cografya", title: "Dış Kuvvetler", summary: "Akarsu, rüzgar, buzul ve dalgalar yeryüzünü aşındırıp biriktirir.", detail: "Dış kuvvetler enerjisini güneşten alır ve yükseltiyi azaltır. Akarsular vadi, delta; rüzgarlar kumul; buzullar sirk gölleri oluşturur.", funFact: "Peribacaları (Kapadokya) rüzgar ve suyun birlikte aşındırmasıyla oluşmuştur.", tags: ["dış kuvvetler", "aşınma"], difficulty: "Orta" },
  { id: "cog8", category: "cografya", title: "İklim Elemanları", summary: "Sıcaklık, basınç, rüzgar, nem ve yağış iklimi oluşturur.", detail: "Sıcaklık enlem, yükselti ve denize uzaklıkla değişir. Alçak basınçta yağış, yüksek basınçta açık hava görülür. Rüzgar yüksek basınçtan alçak basınca eser.", funFact: "Her 100 metre yükselti sıcaklığı ortalama 0,5 °C düşürür.", tags: ["iklim", "iklim elemanları"], difficulty: "Orta" },
  { id: "cog9", category: "cografya", title: "Türkiye'nin Yer Şekilleri", summary: "Türkiye dağlık ve yüksek bir ülkedir; ortalama yükselti fazladır.", detail: "Dağlar genelde doğu-batı uzanır. En yüksek nokta Ağrı Dağı'dır. Ovalar kıyı ve iç bölgelerde bulunur. Akarsular kısa ve rejimleri düzensizdir.", funFact: "Türkiye'nin ortalama yükseltisi yaklaşık 1132 m ile Avrupa ortalamasının çok üstündedir.", tags: ["türkiye", "yer şekilleri"], difficulty: "Orta" },
  { id: "cog10", category: "cografya", title: "Türkiye'nin İklimi ve Bitki Örtüsü", summary: "Üç ana iklim ve buna bağlı orman, maki, bozkır örtüsü görülür.", detail: "Kıyılarda deniz iklimleri, iç kesimlerde karasal iklim etkilidir. Karadeniz'de ormanlar, Akdeniz'de maki, İç Anadolu'da bozkır yaygındır.", funFact: "Türkiye, üç farklı bitki coğrafyası bölgesinin kesiştiği zengin bir floraya sahiptir.", tags: ["türkiye iklimi", "bitki örtüsü"], difficulty: "Orta" },
  { id: "cog11", category: "cografya", title: "Türkiye'de Tarım", summary: "İklim çeşitliliği geniş ürün yelpazesi sağlar.", detail: "Buğday en çok ekilen üründür. Çay Karadeniz'de, pamuk ve narenciye Akdeniz-Ege'de, fındık Karadeniz kıyısında yetişir. Sulama verimi artırır.", funFact: "Türkiye fındık üretiminde dünya lideridir.", tags: ["tarım", "ekonomi coğrafyası"], difficulty: "Orta" },
  { id: "cog12", category: "cografya", title: "Türkiye'de Sanayi ve Enerji", summary: "Marmara Bölgesi sanayinin kalbidir; çeşitli enerji kaynakları kullanılır.", detail: "Hidroelektrik, doğal gaz, kömür, rüzgar ve güneş enerji kaynaklarıdır. GAP tarım ve enerjide büyük bir projedir. Sanayi hammadde ve ulaşıma bağlı yerleşir.", funFact: "GAP kapsamındaki Atatürk Barajı, Türkiye'nin en büyük barajlarından biridir.", tags: ["sanayi", "enerji"], difficulty: "Orta" },
  { id: "cog13", category: "cografya", title: "Doğal Afetler", summary: "Deprem, sel, heyelan, çığ ve kuraklık başlıca doğal afetlerdir.", detail: "Türkiye'de en yıkıcı afet depremdir. Fay hatları üzerinde yer alması riski artırır. Doğru yapılaşma ve bilinç afet zararını azaltır.", funFact: "Kuzey Anadolu Fay Hattı, dünyanın en aktif fay hatlarından biridir.", tags: ["doğal afet", "deprem"], difficulty: "Orta" },
  { id: "cog14", category: "cografya", title: "Nüfus Piramitleri", summary: "Bir ülkenin yaş ve cinsiyet yapısını gösteren grafiklerdir.", detail: "Geniş tabanlı piramit genç ve hızlı artan nüfusu (az gelişmiş ülke), dar tabanlı yaşlı nüfusu (gelişmiş ülke) gösterir.", funFact: "Geniş tabanlı piramit yüksek doğum oranını, dar taban yaşlanan toplumu işaret eder.", tags: ["nüfus", "demografi"], difficulty: "İleri" },
  { id: "cog15", category: "cografya", title: "Küresel Ortam: Kıtalar ve Okyanuslar", summary: "Yedi kıta ve büyük okyanuslar Dünya yüzeyini oluşturur.", detail: "En büyük kıta Asya, en büyük okyanus Pasifik'tir. Kıtaların dağılışı iklim, nüfus ve ekonomiyi etkiler. Levha hareketleri kıtaları yavaşça değiştirir.", funFact: "Kıtalar hâlâ yılda birkaç santimetre hareket ediyor (levha tektoniği).", tags: ["kıtalar", "okyanuslar"], difficulty: "Temel" },

  // ==================== EDEBİYAT ====================
  { id: "ede4", category: "edebiyat", title: "Şiir Bilgisi: Ölçü", summary: "Hece ölçüsü hece sayısına, aruz ölçüsü hecelerin uzunluk-kısalığına dayanır.", detail: "Halk şiiri hece ölçüsüyle yazılır (7'li, 8'li, 11'li). Divan şiiri aruz ölçüsü kullanır. Serbest şiirde ölçü yoktur.", funFact: "Durak, hece ölçüsünde dizenin okunurken bölündüğü yerdir.", tags: ["şiir bilgisi", "ölçü"], difficulty: "Orta" },
  { id: "ede5", category: "edebiyat", title: "Uyak (Kafiye) ve Redif", summary: "Uyak dize sonundaki ses benzerliği, redif aynen tekrarlanan ek/sözcüktür.", detail: "Yarım uyak tek ses, tam uyak iki ses, zengin uyak üç+ ses benzerliğidir. Redif uyaktan sonra gelen, anlamca aynı tekrar eden ögedir.", funFact: "Redif her zaman uyaktan sonra ve dizenin en sonunda yer alır.", tags: ["uyak", "redif", "şiir"], difficulty: "Orta" },
  { id: "ede6", category: "edebiyat", title: "Halk Edebiyatı", summary: "Anonim, âşık ve dini-tasavvufi olarak üçe ayrılır.", detail: "Anonim halk edebiyatında türkü, mani, ninni; âşık edebiyatında koşma, semai, destan; tasavvufi edebiyatta ilahi, nefes bulunur. Sade dil kullanılır.", funFact: "Karacaoğlan âşık edebiyatının, Yunus Emre tasavvufi halk edebiyatının en önemli isimlerindendir.", tags: ["halk edebiyatı", "türk edebiyatı"], difficulty: "Orta" },
  { id: "ede7", category: "edebiyat", title: "Divan Edebiyatı Genel Özellikleri", summary: "Aruz ölçüsü, Arapça-Farsça sözcükler ve mazmunlar kullanılır.", detail: "Nazım birimi genelde beyittir. Konudan çok söyleyiş güzelliğine önem verilir. Mazmunlar (kalıplaşmış imgeler) yaygındır: gül-bülbül, servi-boy.", funFact: "Fuzûlî, Bâkî ve Nedim divan edebiyatının en tanınmış şairlerindendir.", tags: ["divan edebiyatı", "aruz"], difficulty: "İleri" },
  { id: "ede8", category: "edebiyat", title: "Tanzimat Edebiyatı", summary: "Batı etkisinde ilk yenileşme dönemidir; toplumsal fayda amaçlanır.", detail: "I. dönemde (Şinasi, Namık Kemal) toplumcu, sanatı halka yönelik; II. dönemde (Recaizade, Abdülhak Hamit) bireysel ve sanatsal eğilim görülür. Roman, tiyatro, makale girer.", funFact: "İlk özel gazete Tercüman-ı Ahval, Şinasi ve Agah Efendi tarafından çıkarıldı.", tags: ["tanzimat", "edebi dönem"], difficulty: "İleri" },
  { id: "ede9", category: "edebiyat", title: "Servet-i Fünun Edebiyatı", summary: "'Sanat için sanat' anlayışı, ağır dil ve bireysel temalar öne çıkar.", detail: "Tevfik Fikret, Halit Ziya, Cenap Şahabettin dönemin öncüleridir. Roman tekniği gelişti (Aşk-ı Memnu). Aruz Türkçeye başarıyla uygulandı.", funFact: "Halit Ziya Uşaklıgil'in 'Aşk-ı Memnu'su ilk modern Türk romanı sayılır.", tags: ["servet-i fünun", "edebi dönem"], difficulty: "İleri" },
  { id: "ede10", category: "edebiyat", title: "Milli Edebiyat", summary: "Sade dil, hece ölçüsü ve milli kaynaklara dönüş amaçlandı.", detail: "Genç Kalemler dergisi ve 'Yeni Lisan' makalesiyle başladı. Ziya Gökalp, Ömer Seyfettin, Mehmet Emin Yurdakul öncülerdir. Anadolu ve halk konu edildi.", funFact: "Ömer Seyfettin, Türk edebiyatında öykü türünün en önemli temsilcilerindendir.", tags: ["milli edebiyat", "yeni lisan"], difficulty: "İleri" },
  { id: "ede11", category: "edebiyat", title: "Cumhuriyet Dönemi Şiiri", summary: "Öz şiir, Garip (I. Yeni), İkinci Yeni gibi akımlar gelişti.", detail: "Garip akımı (Orhan Veli) ölçü-uyağı reddetti, günlük dili kullandı. İkinci Yeni imgeci ve kapalı bir şiir anlayışı getirdi. Nazım Hikmet serbest şiirin öncüsüdür.", funFact: "Orhan Veli'nin 'Garip' hareketi şiiri sokağın diline yaklaştırdı.", tags: ["cumhuriyet edebiyatı", "şiir"], difficulty: "İleri" },
  { id: "ede12", category: "edebiyat", title: "Cumhuriyet Dönemi Romanı", summary: "Anadolu, toplumsal gerçekçilik ve bireysel temalar işlendi.", detail: "Yakup Kadri, Reşat Nuri, Halide Edip toplumsal konuları; Sabahattin Ali, Yaşar Kemal köy gerçekliğini anlattı. Ahmet Hamdi Tanpınar zaman ve bireyi işledi.", funFact: "Yaşar Kemal'in 'İnce Memed'i Türk edebiyatının en çok çevrilen romanlarındandır.", tags: ["cumhuriyet edebiyatı", "roman"], difficulty: "İleri" },
  { id: "ede13", category: "edebiyat", title: "Edebi Türler: Roman ve Hikaye", summary: "Roman geniş kapsamlı, hikaye kısa ve tek olay eksenlidir.", detail: "Hikayede olay (Maupassant) veya durum (Çehov) öne çıkabilir. Romanda çok sayıda kişi ve olay örgüsü bulunur. İkisi de kurmaca (itibari) metinlerdir.", funFact: "Durum hikayesinde belirgin bir olay değil, bir an ve atmosfer anlatılır.", tags: ["edebi türler", "roman", "hikaye"], difficulty: "Orta" },
  { id: "ede14", category: "edebiyat", title: "Edebi Türler: Tiyatro", summary: "Trajedi, komedi ve dram temel tiyatro türleridir.", detail: "Trajedi soylu kişilerin acıklı sonunu anlatır, üç birlik kuralına uyar. Komedi güldürerek düşündürür. Dram acı ve sevinci bir arada yaşamdan alır.", funFact: "Modern tiyatronun öncüsü sayılan dram türünü Shakespeare geliştirmiştir.", tags: ["tiyatro", "edebi türler"], difficulty: "Orta" },
  { id: "ede15", category: "edebiyat", title: "Öğretici Metinler", summary: "Makale, deneme, fıkra, gezi, anı, biyografi öğretici türlerdir.", detail: "Makale bir düşünceyi kanıtlarla savunur. Deneme kişisel ve serbesttir. Fıkra güncel konuyu kısaca ele alır. Anı yaşanmışı sonradan anlatır.", funFact: "Deneme türünün kurucusu Fransız yazar Montaigne'dir.", tags: ["öğretici metin", "edebi türler"], difficulty: "Orta" },

  // ==================== FELSEFE ====================
  { id: "fel3", category: "felsefe", title: "Felsefeye Giriş", summary: "Felsefe, varlık, bilgi ve değer üzerine akla dayalı, sistemli düşünmedir.", detail: "Merak ve hayretle başlar, sürekli sorgular. Kesin sonuçlara ulaşmaktan çok doğru soruları sormayı amaçlar. Bilimden farkı deneysel olmamasıdır.", funFact: "'Felsefe' sözcüğü Yunanca 'bilgelik sevgisi' (philo-sophia) anlamına gelir.", tags: ["felsefe", "giriş"], difficulty: "Temel" },
  { id: "fel4", category: "felsefe", title: "Varlık Felsefesi (Ontoloji)", summary: "Varlığın var olup olmadığını ve neden ibaret olduğunu inceler.", detail: "İdealizm varlığı düşünce/ruh, materyalizm madde olarak görür. Realizm varlığın bilinçten bağımsız var olduğunu savunur. Nihilizm varlığı reddeder.", funFact: "Platon'a göre gerçek varlık, duyularla algıladığımız değil, idealardır.", tags: ["ontoloji", "varlık"], difficulty: "İleri" },
  { id: "fel5", category: "felsefe", title: "Bilgi Kuramında Doğruluk", summary: "Bir bilginin doğruluğu; uygunluk, tutarlılık ve fayda ölçütleriyle sınanır.", detail: "Uygunluk kuramı bilgiyi nesneyle karşılaştırır. Tutarlılık kuramı iç çelişkisizliğe bakar. Pragmatizm ise yararlı olanı doğru sayar.", funFact: "Pragmatizme göre bir düşünce işe yarıyorsa doğrudur; öncüsü William James'tir.", tags: ["bilgi", "doğruluk"], difficulty: "İleri" },
  { id: "fel6", category: "felsefe", title: "Bilim Felsefesi", summary: "Bilimin yöntemini, gelişimini ve sınırlarını inceler.", detail: "Ürün olarak bilim (klasik görüş) bilgiyi birikimsel görür. Etkinlik olarak bilim (Kuhn) paradigma değişimlerini vurgular. Bilim gözlem, hipotez ve deneyle ilerler.", funFact: "Karl Popper'a göre bir teori bilimseldir ancak yanlışlanabilir olmalıdır.", tags: ["bilim felsefesi", "yöntem"], difficulty: "İleri" },
  { id: "fel7", category: "felsefe", title: "Siyaset Felsefesi", summary: "Devlet, iktidar, adalet ve özgürlük kavramlarını sorgular.", detail: "Toplum sözleşmesi kuramcıları (Hobbes, Locke, Rousseau) devletin kökenini açıklar. İdeal devlet, egemenlik, meşruiyet temel sorulardır.", funFact: "Hobbes'a göre devlet olmadan yaşam 'herkesin herkese karşı savaşı'dır.", tags: ["siyaset felsefesi", "devlet"], difficulty: "İleri" },
  { id: "fel8", category: "felsefe", title: "Sanat Felsefesi (Estetik)", summary: "Güzellik, sanat ve beğeni üzerine düşünür.", detail: "Sanatı taklit (Platon, Aristoteles), yaratma veya oyun olarak açıklayan görüşler vardır. Güzelin nesnel mi öznel mi olduğu temel tartışmadır.", funFact: "Aristoteles'e göre sanat, doğanın taklidi (mimesis) yoluyla arınma (katharsis) sağlar.", tags: ["estetik", "sanat"], difficulty: "Orta" },
  { id: "fel9", category: "felsefe", title: "Din Felsefesi", summary: "Tanrı, inanç ve dinin akılla ilişkisini ele alır.", detail: "Teizm bir Tanrı'yı kabul eder, ateizm reddeder, agnostisizm bilinemeyeceğini savunur, deizm evrene karışmayan bir Tanrı'yı öne sürer.", funFact: "Deizme göre Tanrı evreni yaratmış ama işleyişine müdahale etmez.", tags: ["din felsefesi", "inanç"], difficulty: "Orta" },
  { id: "fel10", category: "felsefe", title: "İlk Çağ Felsefesi", summary: "Doğa filozoflarıyla başlar, Sokrates-Platon-Aristoteles ile doruğa çıkar.", detail: "Thales her şeyin sudan oluştuğunu söyledi. Sokrates 'kendini bil' dedi ve diyalog yöntemini kullandı. Aristoteles mantığın kurucusudur.", funFact: "Sokrates hiç yazılı eser bırakmadı; düşünceleri öğrencisi Platon aracılığıyla bilinir.", tags: ["ilk çağ", "felsefe tarihi"], difficulty: "Orta" },
  { id: "fel11", category: "felsefe", title: "Mantık", summary: "Doğru düşünmenin kurallarını inceleyen disiplindir.", detail: "Önerme doğru ya da yanlış olabilen yargıdır. Kıyas (tümdengelim) öncüllerden zorunlu sonuç çıkarır. Tümevarım tekilden genele gider.", funFact: "'Tüm insanlar ölümlüdür, Sokrates insandır, öyleyse Sokrates ölümlüdür' klasik kıyas örneğidir.", tags: ["mantık", "akıl yürütme"], difficulty: "İleri" },
  { id: "fel12", category: "felsefe", title: "Ahlak Felsefesinde Özgürlük", summary: "Determinizm, indeterminizm ve otodeterminizm irade özgürlüğünü tartışır.", detail: "Determinizm her şeyin nedene bağlı olduğunu, dolayısıyla özgürlüğün olmadığını savunur. İndeterminizm mutlak özgürlüğü, otodeterminizm ise akla dayalı iradeyi öne sürer.", funFact: "Ahlaki sorumluluk, ancak irade özgürlüğü varsa mümkün olabilir.", tags: ["etik", "özgürlük"], difficulty: "İleri" },
];
